-- Fragmento PL/pgSQL idempotente, casando por SLUG (nunca UUID), no estilo de
-- supabase/migrations/20260920000000_composicoes_conforme_rotulo.sql.
-- Fonte: docs/conformidade/reformulacao/multi-vitta-gestante-e-lactante-em-capsula.md e scratchpad/fase2/multi-vitta-gestante-e-lactante-em-capsula.json.
-- Sem guarda de contagem aqui (a consolidação põe); só o bloco deste produto.
-- NÃO APLICADO em nenhum banco. Veredito esperado: CONFORME CONDICIONADO A (laudo novo do bisglicinato de magnésio; laudos de bisglicinato ferroso e bisglicinato de cobre; emissão do memorial de cálculo pelo RT) — e à decisão do dono sobre completar ou não os nutrientes citados sem dose
-- =====================================================================================

-- 1. exclusão lógica das composições ativas atuais desta fórmula
update public.formula_compositions fc
set active = false, deleted_at = now(), reason_deleted = 'reformulação regulatória 2026-09-16'
from public.formulas f
where f.id = fc.formula_id and f.deleted_at is null and f.slug = 'multi-vitta-gestante-e-lactante-em-capsula'
  and fc.deleted_at is null
  and coalesce(fc.metadata->>'fonte', '') <> 'reformulacao_2026-09-16';

